/// <summary>
///Return order and claims Business events
/// </summary>
[BusinessEvents(classStr(METClaimSOInvoicedBusinessEventContract), 'MET:ClaimSalesOrderInvoicedBE', 'MET:ClaimSalesOrderInvoicedBEDesc', ModuleAxapta::SalesOrder)]
public final class METClaimSOInvoicedBusinessEvent extends BusinessEventsBase
{
    private SalesTable salestable;

}

Method.Source:
/// <summary>
/// Constructs a new METClaimSOInvoicedBusinessEventContract business event data contract.
/// </summary>
/// <returns>
/// A new <c>METClaimSOInvoicedBusinessEventContract</c> business event data contract.
/// </returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return METClaimSOInvoicedBusinessEventContract::newFromSalesTable(salestable);
}

/// <summary>
/// Parameter method for sales table
/// </summary>
/// <param name = "_salesTable">SalesTable reference</param>
/// <returns>SalesTable</returns>
public SalesTable parmSalesTable(SalesTable _salesTable = salestable)
{
    salestable = _salesTable;

    return salestable;
}

/// <summary>
/// Creates a <c>METClaimSOInvoicedBusinessEvent</c> from a <c>SalesTable</c> record.
/// </summary>
/// <param name = "_salesTable"> A sales order record.</param>
/// <returns>An instance of <c>METClaimSOInvoicedBusinessEvent</c>.</returns>
public static METClaimSOInvoicedBusinessEvent newFromSalesTable(SalesTable _salesTable)
{
    METClaimSOInvoicedBusinessEvent businessEvent = new METClaimSOInvoicedBusinessEvent();
    businessEvent.parmSalesTable(_salesTable);

    return businessEvent;
}
